<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { api } from '@/api/client'
import { invalidateCatalog } from '@/api/content'
type Tab='overview'|'content'|'guestbook'|'comments'|'media'|'profile'|'users'|'audit'
interface Content {id:number;kind:'post'|'project';slug:string;title:string;summary:string;content:string;status:'draft'|'published'|'archived';featured:boolean;sort_order:number;cover_url:string|null;github_url:string|null;updated_at:string}
interface Entry {id:number;content:string;nickname:string;created_at:string;is_deleted:boolean;article_slug?:string}
interface Media {id:number;original_name:string;public_url:string;thumbnail_url:string;mime_type:string;size_bytes:number;alt_text:string;created_at:string}
const nav:{id:Tab;label:string}[]=[{id:'overview',label:'工作台'},{id:'content',label:'文章与项目'},{id:'guestbook',label:'留言管理'},{id:'comments',label:'评论管理'},{id:'media',label:'图片素材库'},{id:'profile',label:'关于我'},{id:'users',label:'用户管理'},{id:'audit',label:'操作日志'}]
const tab=ref<Tab>('overview'),loading=ref(false),busy=ref(false),notice=ref(''),error=ref('')
const stats=ref({users:0,active_users:0,comments:0,guestbook_messages:0})
const contents=ref<Content[]>([]),messages=ref<Entry[]>([]),comments=ref<Entry[]>([]),mediaAssets=ref<Media[]>([]),users=ref<any[]>([]),logs=ref<any[]>([])
const filter=reactive({kind:'',status:'',keyword:''}),includeDeleted=ref(false),keyword=ref('')
const selectedContentIds=ref<number[]>([]),bulkStatus=ref(''),selectedModerationIds=ref<number[]>([]),uploading=ref(false)
const categories=ref<Array<{id:number;name:string}>>([]),tags=ref<Array<{id:number;name:string}>>([]),bulkCategoryIds=ref<number[]>([]),bulkTagIds=ref<number[]>([]),bulkSortOrder=ref<number|null>(null)
const selectAllContent=computed({get:()=>filtered.value.length>0&&filtered.value.every(x=>selectedContentIds.value.includes(x.id)),set:(checked:boolean)=>{selectedContentIds.value=checked?[...new Set([...selectedContentIds.value,...filtered.value.map(x=>x.id)])]:selectedContentIds.value.filter(id=>!filtered.value.some(x=>x.id===id))}})
const filteredEntries=computed(()=>((tab.value==='guestbook'?messages.value:comments.value).filter(x=>(x.nickname+' '+x.content+' '+(x.article_slug||'')).toLowerCase().includes(keyword.value.toLowerCase()))))
const filtered=computed(()=>contents.value.filter(x=>(!filter.kind||x.kind===filter.kind)&&(!filter.status||x.status===filter.status)&&(!filter.keyword||[x.title,x.slug].join(' ').toLowerCase().includes(filter.keyword.toLowerCase()))))
const editor=ref(false),editId=ref<number|null>(null)
const draft=reactive({kind:'post' as 'post'|'project',slug:'',title:'',summary:'',content:'',status:'draft' as 'draft'|'published'|'archived',featured:false,sort_order:0,cover_url:'',github_url:''})
const profile=reactive({name:'半夏',headline:'一名热爱技术、喜欢动手实践的开发者。',bio:'以代码记录成长，以思考探索世界。在技术与生活之间，保持好奇，持续前行。',email:'dhq1015@gmail.com',github_url:'https://github.com/banxia-prgo',avatar_url:'',intro_title:'持续探索的方向',note_title:'关于这里',note_paragraphs:'「半夏小筑」是我的个人数字空间。这里记录技术学习中的问题与解法，收纳亲手完成的项目，也留下一些关于成长和生活的思考。\n如果你对某篇文章或某个项目有想法，欢迎到留言板交流。',directions:[
{title:'机器视觉',eyebrow:'01 / VISION',description:'围绕 OpenCV、图像处理、目标检测与工业视觉应用，积累可运行、可复现的实践经验。',tags:'OpenCV · C++ · Qt'},
{title:'深度学习',eyebrow:'02 / AI',description:'学习神经网络、图像分类与目标检测，尝试从数据准备、模型训练走向实际应用。',tags:'Python · PyTorch · YOLO'},
{title:'工程实践',eyebrow:'03 / ENGINEERING',description:'关注软件架构、开发工具链、Linux 环境与项目部署，让想法成为稳定可用的作品。',tags:'Git · Linux · Docker'}] as Array<{title:string;eyebrow:string;description:string;tags:string}>})
function msg(s:string,bad=false){notice.value=bad?'':s;error.value=bad?s:''}
async function refresh(){loading.value=true;try{const [s,c,u,l]=await Promise.all([api.get('/api/admin/overview'),api.get<Content[]>('/api/admin/content?limit=100'),api.get('/api/admin/users?limit=100'),api.get('/api/admin/audit-logs?limit=100')]);stats.value=s.data;contents.value=c.data;users.value=u.data.items;logs.value=l.data;await Promise.all([loadMessages(),loadComments(),loadTaxonomies()])}catch(e){msg(e instanceof Error?e.message:'加载失败',true)}finally{loading.value=false}}
async function loadMessages(){messages.value=(await api.get<Entry[]>('/api/admin/guestbook?include_deleted='+includeDeleted.value)).data}
async function loadComments(){comments.value=(await api.get<Entry[]>('/api/admin/comments?include_deleted='+includeDeleted.value)).data}
async function loadMedia(){mediaAssets.value=(await api.get<Media[]>('/api/admin/media?limit=100')).data}
async function loadTaxonomies(){const [c,t]=await Promise.all([api.get('/api/admin/categories'),api.get('/api/admin/tags')]);categories.value=c.data;tags.value=t.data}
async function loadProfile(){try{const d=(await api.get<Record<string,any>>('/api/site/profile')).data;if(d&&Object.keys(d).length)Object.assign(profile,{...d,note_paragraphs:Array.isArray(d.note_paragraphs)?d.note_paragraphs.join('\n'):profile.note_paragraphs,directions:Array.isArray(d.directions)?d.directions.map((x:any)=>({...x,tags:Array.isArray(x.tags)?x.tags.join(' · '):x.tags||''})):profile.directions})}catch(e){msg(e instanceof Error?e.message:'资料加载失败',true)}}
async function go(t:Tab){tab.value=t;if(t==='profile')await loadProfile();if(t==='guestbook')await loadMessages();if(t==='comments')await loadComments();if(t==='media')await loadMedia();selectedModerationIds.value=[]}
function reset(){editId.value=null;Object.assign(draft,{kind:'post',slug:'',title:'',summary:'',content:'',status:'draft',featured:false,sort_order:0,cover_url:'',github_url:''})}
function edit(x:Content){editId.value=x.id;Object.assign(draft,{...x,cover_url:x.cover_url||'',github_url:x.github_url||''});editor.value=true}
async function saveContent(){busy.value=true;try{const data={...draft,cover_url:draft.cover_url||null,github_url:draft.github_url||null};if(editId.value)await api.patch('/api/admin/content/'+editId.value,data);else await api.post('/api/admin/content',data);editor.value=false;reset();invalidateCatalog();await refresh();msg('内容已保存')}catch(e){msg(e instanceof Error?e.message:'保存失败',true)}finally{busy.value=false}}
async function quickSave(x:Content){try{await api.patch('/api/admin/content/'+x.id,{title:x.title,status:x.status,sort_order:x.sort_order,featured:x.featured});invalidateCatalog();msg('表格修改已保存')}catch(e){msg(e instanceof Error?e.message:'保存失败',true)}}
async function removeContent(x:Content){if(!confirm('确定永久删除「'+x.title+'」？'))return;try{await api.delete('/api/admin/content/'+x.id);invalidateCatalog();await refresh();msg('内容已删除')}catch(e){msg(e instanceof Error?e.message:'删除失败',true)}}
async function moderate(x:Entry,type:'guestbook'|'comments',restore=false){if(!restore&&!confirm('确定隐藏这条记录？隐藏后可随时恢复。'))return;try{if(restore)await api.post('/api/admin/'+type+'/'+x.id+'/restore');else await api.delete((type==='guestbook'?'/api/guestbook/messages/':'/api/comments/')+x.id);if(type==='guestbook')await loadMessages();else await loadComments();await refreshStats();msg(restore?'记录已恢复':'记录已隐藏')}catch(e){msg(e instanceof Error?e.message:'操作失败',true)}}
async function refreshStats(){stats.value=(await api.get('/api/admin/overview')).data}

async function bulkUpdateContent(extra:Record<string,unknown>){if(!selectedContentIds.value.length)return;busy.value=true;try{const r=await api.patch('/api/admin/content-bulk',{ids:selectedContentIds.value,...extra});invalidateCatalog();selectedContentIds.value=[];await refresh();msg('已批量更新 '+r.data.updated+' 项内容')}catch(e){msg(e instanceof Error?e.message:'批量更新失败',true)}finally{busy.value=false}}
async function applyBulkStatus(){if(!bulkStatus.value){msg('请先选择目标状态',true);return}await bulkUpdateContent({status:bulkStatus.value});bulkStatus.value=''}
async function applyBulkCategories(){await bulkUpdateContent({category_ids:bulkCategoryIds.value});bulkCategoryIds.value=[]}
async function applyBulkTags(){await bulkUpdateContent({tag_ids:bulkTagIds.value});bulkTagIds.value=[]}
async function applyBulkSort(){if(bulkSortOrder.value===null){msg('请先填写排序值',true);return}await bulkUpdateContent({sort_order:bulkSortOrder.value})}
async function bulkDeleteContent(){if(!selectedContentIds.value.length||!confirm('确定永久删除选中的 '+selectedContentIds.value.length+' 项内容？此操作不可恢复。'))return;busy.value=true;try{const r=await api.post('/api/admin/content/bulk-delete',{ids:selectedContentIds.value});invalidateCatalog();selectedContentIds.value=[];await refresh();msg('已删除 '+r.data.deleted+' 项内容')}catch(e){msg(e instanceof Error?e.message:'批量删除失败',true)}finally{busy.value=false}}
async function bulkModerate(action:'hide'|'restore'){if(!selectedModerationIds.value.length)return;busy.value=true;try{await api.post('/api/admin/moderation/bulk',{kind:tab.value,ids:selectedModerationIds.value,action});selectedModerationIds.value=[];if(tab.value==='guestbook')await loadMessages();else await loadComments();await refreshStats();msg(action==='hide'?'所选内容已隐藏':'所选内容已恢复')}catch(e){msg(e instanceof Error?e.message:'审核操作失败',true)}finally{busy.value=false}}
async function uploadFileList(files:File[]){if(!files.length)return;uploading.value=true;try{for(const file of files){const form=new FormData();form.append('file',file);form.append('alt_text',file.name.replace(/\.[^.]+$/,''));await api.post('/api/admin/media/upload',form)}await loadMedia();msg('成功上传 '+files.length+' 张图片')}catch(e){msg(e instanceof Error?e.message:'图片上传失败',true);await loadMedia()}finally{uploading.value=false}}
async function uploadFiles(event:Event){const input=event.target as HTMLInputElement;const files=Array.from(input.files||[]);await uploadFileList(files);input.value=''}
function handleMediaDrop(event:DragEvent){void uploadFileList(Array.from(event.dataTransfer?.files||[]))}
async function deleteMedia(item:Media){if(!confirm('确定删除图片「'+item.original_name+'」？如果文章或项目正在引用，将无法删除。'))return;try{await api.delete('/api/admin/media/'+item.id);await loadMedia();msg('图片已删除')}catch(e){msg(e instanceof Error?e.message:'删除失败',true)}}
async function copyMedia(item:Media,markdown=false){const value=markdown?'!['+(item.alt_text||item.original_name)+']('+item.public_url+')':item.public_url;try{await navigator.clipboard.writeText(value);msg(markdown?'Markdown 图片引用已复制':'图片地址已复制')}catch{msg('复制失败，请手动复制：'+value,true)}}
function useAsCover(item:Media){draft.cover_url=item.public_url;tab.value='content';editor.value=true;msg('图片地址已填入封面字段')}
function toggleAllModeration(event:Event){const checked=(event.target as HTMLInputElement).checked;selectedModerationIds.value=checked?filteredEntries.value.map(x=>x.id):[]}
function addDirection(){profile.directions.push({title:'',eyebrow:'',description:'',tags:''})}
async function saveProfile(){busy.value=true;try{const value={...profile,note_paragraphs:profile.note_paragraphs.split('\n').map(x=>x.trim()).filter(Boolean),directions:profile.directions.map((x,i)=>({...x,sort_order:i+1,tags:x.tags.split(/[·,，]/).map(t=>t.trim()).filter(Boolean)}))};await api.put('/api/admin/site-settings/profile',{value});msg('资料已保存，前台刷新后即可查看')}catch(e){msg(e instanceof Error?e.message:'保存失败',true)}finally{busy.value=false}}
async function toggleUser(x:any){try{await api.patch('/api/admin/users/'+x.id,{is_active:!x.is_active});await refresh();msg('用户状态已更新')}catch(e){msg(e instanceof Error?e.message:'更新失败',true)}}
onMounted(()=>void refresh())
</script>
<template>
<div class="admin-layout">
<aside class="sidebar"><div class="brand"><span>半</span><b>半夏小筑<small>CONTENT STUDIO</small></b></div><p class="nav-caption">工作空间</p><button v-for="n in nav" :key="n.id" :class="{active:tab===n.id}" @click="go(n.id)">{{n.label}}</button><div class="side-foot">● 管理模式已启用</div></aside>
<main class="main"><header class="topbar"><span>管理后台　/　<b>{{nav.find(x=>x.id===tab)?.label}}</b></span><button @click="refresh" :disabled="loading">{{loading?'同步中…':'↻ 刷新数据'}}</button></header><div class="workspace">
<header class="heading"><p>BANXIA STUDIO / CONTROL ROOM</p><h1>{{nav.find(x=>x.id===tab)?.label}}</h1><span>把网站内容与日常维护，整理成清晰易用的工作台。</span></header>
<p v-if="notice" class="notice">{{notice}}</p><p v-if="error" class="error">{{error}}</p>
<section v-if="tab==='overview'">
<div class="stats"><article><small>注册用户</small><b>{{stats.users}}</b></article><article><small>正常用户</small><b>{{stats.active_users}}</b></article><article><small>文章评论</small><b>{{stats.comments}}</b></article><article><small>公开留言</small><b>{{stats.guestbook_messages}}</b></article></div>
<div class="panel welcome"><div><h2>今天想更新什么？</h2><p>在表格中维护内容，保存后同步到网站。</p></div><div><button class="primary" @click="go('content');reset();editor=true">＋ 发布新内容</button> <button @click="go('profile')">编辑关于我</button> <button @click="go('guestbook')">处理留言</button></div></div>
<div class="panel"><h2>最近更新</h2><table><thead><tr><th>标题</th><th>类型</th><th>状态</th><th>更新时间</th></tr></thead><tbody><tr v-for="x in contents.slice(0,6)" :key="x.id"><td>{{x.title}}</td><td>{{x.kind==='post'?'文章':'项目'}}</td><td>{{x.status}}</td><td>{{x.updated_at?new Date(x.updated_at).toLocaleDateString():'—'}}</td></tr></tbody></table></div>
</section>
<section v-else-if="tab==='content'" class="panel"><div class="panel-head"><div><h2>文章与项目</h2><p>标题、状态、排序和精选可直接在表格中修改。</p></div><button class="primary" @click="reset();editor=true">＋ 新建内容</button></div>
<div class="toolbar"><input v-model="filter.keyword" placeholder="搜索标题或 Slug"><select v-model="filter.kind"><option value="">全部类型</option><option value="post">文章</option><option value="project">项目</option></select><select v-model="filter.status"><option value="">全部状态</option><option value="draft">草稿</option><option value="published">已发布</option><option value="archived">归档</option></select></div><div v-if="selectedContentIds.length" class="bulk-toolbar"><span>已选 {{selectedContentIds.length}} 项</span><select v-model="bulkStatus"><option value="">批量修改状态…</option><option value="draft">转为草稿</option><option value="published">立即发布</option><option value="archived">归档</option></select><button @click="applyBulkStatus" :disabled="busy">应用状态</button><select multiple v-model="bulkCategoryIds" class="bulk-select" title="按住 Ctrl 可多选分类"><option v-for="item in categories" :key="item.id" :value="item.id">{{item.name}}</option></select><select multiple v-model="bulkTagIds" class="bulk-select" title="按住 Ctrl 可多选标签"><option v-for="item in tags" :key="item.id" :value="item.id">{{item.name}}</option></select><button @click="applyBulkCategories" :disabled="busy">应用分类</button><button @click="applyBulkTags" :disabled="busy">应用标签</button><input v-model.number="bulkSortOrder" class="bulk-sort" type="number" placeholder="排序值" aria-label="批量排序值"><button @click="applyBulkSort" :disabled="busy">统一排序</button><button @click="bulkUpdateContent({featured:true})" :disabled="busy">批量设为精选</button><button @click="bulkUpdateContent({featured:false})" :disabled="busy">取消精选</button><button class="danger" @click="bulkDeleteContent" :disabled="busy">批量删除</button></div>
<table><thead><tr><th><input type="checkbox" v-model="selectAllContent" aria-label="选择当前筛选结果"></th><th>标题</th><th>类型</th><th>状态</th><th>排序</th><th>精选</th><th>操作</th></tr></thead><tbody><tr v-for="x in filtered" :key="x.id"><td><input type="checkbox" v-model="selectedContentIds" :value="x.id"></td><td><input v-model="x.title" class="cell"><small>{{x.slug}}</small></td><td>{{x.kind==='post'?'文章':'项目'}}</td><td><select v-model="x.status" class="cell"><option value="draft">草稿</option><option value="published">已发布</option><option value="archived">归档</option></select></td><td><input v-model.number="x.sort_order" type="number" class="cell number"></td><td><input v-model="x.featured" type="checkbox"></td><td class="actions"><button @click="quickSave(x)">保存行</button><button @click="edit(x)">编辑正文</button><button class="danger" @click="removeContent(x)">删除</button></td></tr><tr v-if="!filtered.length"><td colspan="7" class="empty">没有匹配内容。</td></tr></tbody></table>
</section>
<section v-else-if="tab==='guestbook'||tab==='comments'" class="panel"><div class="panel-head"><div><h2>{{tab==='guestbook'?'留言列表':'文章评论'}}</h2><p>新内容立即公开；管理员可事后隐藏或恢复，所有操作写入日志。</p></div><label><input type="checkbox" v-model="includeDeleted" @change="tab==='guestbook'?loadMessages():loadComments()"> 显示已隐藏</label></div><div class="bulk-toolbar"><label><input type="checkbox" :checked="filteredEntries.length>0&&filteredEntries.every(x=>selectedModerationIds.includes(x.id))" @change="toggleAllModeration"> 全选当前结果</label><span v-if="selectedModerationIds.length">已选 {{selectedModerationIds.length}} 条</span><button @click="bulkModerate('hide')" :disabled="!selectedModerationIds.length||busy">批量隐藏</button><button @click="bulkModerate('restore')" :disabled="!selectedModerationIds.length||busy">批量恢复</button></div><input v-model="keyword" class="search" placeholder="搜索作者、内容或文章标识"><table><thead><tr><th>选择</th><th>作者</th><th>内容</th><th v-if="tab==='comments'">文章</th><th>时间</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="x in filteredEntries" :key="x.id"><td><input type="checkbox" v-model="selectedModerationIds" :value="x.id"></td><td>{{x.nickname}}</td><td class="long-text">{{x.content}}</td><td v-if="tab==='comments'">{{x.article_slug}}</td><td>{{new Date(x.created_at).toLocaleString()}}</td><td>{{x.is_deleted?'已隐藏':'公开'}}</td><td><button v-if="!x.is_deleted" class="danger" @click="moderate(x,tab==='guestbook'?'guestbook':'comments')">隐藏</button><button v-else @click="moderate(x,tab==='guestbook'?'guestbook':'comments',true)">恢复</button></td></tr><tr v-if="!(tab==='guestbook'?messages:comments).length"><td colspan="7" class="empty">暂无记录</td></tr></tbody></table></section>
<section v-else-if="tab==='media'" class="panel"><div class="panel-head"><div><h2>图片素材库</h2><p>支持 JPG、PNG、WEBP；单张不超过 4 MiB，上传后自动生成缩略图。</p></div><label class="upload-button">{{uploading?'上传中…':'＋ 批量上传图片'}}<input type="file" accept="image/jpeg,image/png,image/webp" multiple :disabled="uploading" @change="uploadFiles"></label></div><div class="dropzone" @dragover.prevent @drop.prevent="handleMediaDrop">将图片拖到这里批量上传，或点击上方按钮选择文件</div><div v-if="!mediaAssets.length" class="empty">素材库暂时为空，选择图片开始上传。</div><div class="media-grid"><article v-for="m in mediaAssets" :key="m.id" class="media-card"><img :src="m.thumbnail_url" :alt="m.alt_text||m.original_name" loading="lazy"><div class="media-info"><strong :title="m.original_name">{{m.original_name}}</strong><small>{{(m.size_bytes/1024).toFixed(1)}} KB · {{m.mime_type}}</small><div class="media-actions"><button @click="copyMedia(m)">复制地址</button><button @click="copyMedia(m,true)">复制 Markdown</button><button @click="useAsCover(m)">设为封面</button><button class="danger" @click="deleteMedia(m)">删除</button></div></div></article></div></section>
<section v-else-if="tab==='profile'">
<div class="panel"><div class="panel-head"><div><h2>基本资料</h2><p>修改后同步到前台关于我页面。</p></div><button class="primary" :disabled="busy" @click="saveProfile">{{busy?'保存中…':'保存全部修改'}}</button></div><div class="form-grid"><label>显示名称<input v-model="profile.name"></label><label>个人身份介绍<input v-model="profile.headline"></label><label class="wide">页面简介<textarea v-model="profile.bio"></textarea></label><label>联系邮箱<input v-model="profile.email"></label><label>GitHub 地址<input v-model="profile.github_url"></label><label class="wide">头像地址<input v-model="profile.avatar_url"></label><label>方向区块标题<input v-model="profile.intro_title"></label><label>个人说明标题<input v-model="profile.note_title"></label><label class="wide">关于这里（每行一段）<textarea v-model="profile.note_paragraphs" rows="4"></textarea></label></div></div>
<div class="panel"><div class="panel-head"><div><h2>技术与学习方向</h2><p>新增、编辑、删除方向卡片，前台自动同步。</p></div><button @click="addDirection">＋ 添加方向</button></div><div class="direction-row heading-row"><span>方向名称</span><span>英文标识</span><span>介绍</span><span>技术标签</span><span>操作</span></div><div v-for="(d,i) in profile.directions" :key="i" class="direction-row"><input v-model="d.title" placeholder="方向名称"><input v-model="d.eyebrow" placeholder="01 / AREA"><textarea v-model="d.description" rows="2" placeholder="方向介绍"></textarea><input v-model="d.tags" placeholder="OpenCV · C++ · Qt"><button class="danger" @click="profile.directions.splice(i,1)">移除</button></div></div>
</section>
<section v-else-if="tab==='users'" class="panel"><h2>注册用户</h2><table><thead><tr><th>昵称</th><th>邮箱</th><th>角色</th><th>注册时间</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td>{{u.nickname}}</td><td>{{u.email}}</td><td>{{u.role}}</td><td>{{new Date(u.created_at).toLocaleDateString()}}</td><td>{{u.is_active?'正常':'已停用'}}</td><td><button @click="toggleUser(u)">{{u.is_active?'停用':'启用'}}</button></td></tr></tbody></table></section>
<section v-else class="panel"><h2>管理员操作日志</h2><table><thead><tr><th>操作人</th><th>动作</th><th>对象</th><th>详情</th><th>时间</th></tr></thead><tbody><tr v-for="(x,i) in logs" :key="x.id||i"><td>{{x.actor_nickname||'—'}}</td><td>{{x.action}}</td><td>{{x.target_type}} / {{x.target_id}}</td><td>{{x.detail||'—'}}</td><td>{{x.created_at?new Date(x.created_at).toLocaleString():'—'}}</td></tr></tbody></table></section>
</div>
<div v-if="editor" class="overlay" @click.self="editor=false"><section class="drawer"><div class="panel-head"><h2>{{editId?'编辑内容':'发布新内容'}}</h2><button @click="editor=false">关闭 ×</button></div><form @submit.prevent="saveContent"><div class="form-grid"><label>内容类型<select v-model="draft.kind"><option value="post">文章</option><option value="project">项目</option></select></label><label>发布状态<select v-model="draft.status"><option value="draft">草稿</option><option value="published">立即发布</option><option value="archived">归档</option></select></label><label class="wide">标题<input v-model="draft.title" required></label><label class="wide">Slug<input v-model="draft.slug" required></label><label class="wide">摘要<input v-model="draft.summary"></label><label>封面地址<input v-model="draft.cover_url"></label><label>GitHub 地址<input v-model="draft.github_url"></label><label class="wide">正文（Markdown）<textarea v-model="draft.content" rows="18" placeholder="# 标题&#10;&#10;在这里编写正文…"></textarea></label><label><input v-model="draft.featured" type="checkbox"> 首页精选</label></div><p><button class="primary" :disabled="busy">{{busy?'保存中…':'保存内容'}}</button></p></form></section></div>
</main></div>
</template>
